import java.util.Map;

public final class AzureClientConfiguration {
    private final TokenCredential credential;
    private final String storageEndpoint;
    private final String vaultEndpoint;
    private final String keyName;
    private final String containerName;

    private AzureClientConfiguration(
            TokenCredential credential,
            String storageEndpoint,
            String vaultEndpoint,
            String keyName,
            String containerName) {
        this.credential = credential;
        this.storageEndpoint = storageEndpoint;
        this.vaultEndpoint = vaultEndpoint;
        this.keyName = keyName;
        this.containerName = containerName;
    }

    public static AzureClientConfiguration fromEnvironment() {
        Map<String, String> environment = System.getenv();
        ManagedIdentityCredentialBuilder credentialBuilder = new ManagedIdentityCredentialBuilder();
        String clientId = environment.get("AZURE_CLIENT_ID");
        if (clientId != null && !clientId.isBlank()) {
            credentialBuilder.clientId(clientId);
        }

        return new AzureClientConfiguration(
                credentialBuilder.build(),
                requireEnvironmentVariable(environment, "AZURE_STORAGE_BLOB_ENDPOINT"),
                requireEnvironmentVariable(environment, "AZURE_KEY_VAULT_ENDPOINT"),
                requireEnvironmentVariable(environment, "AZURE_KEY_VAULT_KEY_NAME"),
                requireEnvironmentVariable(environment, "AZURE_STORAGE_CONTAINER"));
    }

    public BlobServiceClient blobServiceClient() {
        return new BlobServiceClientBuilder()
                .endpoint(storageEndpoint)
                .credential(credential)
                .buildClient();
    }

    public BlobServiceAsyncClient blobServiceAsyncClient() {
        return new BlobServiceClientBuilder()
                .endpoint(storageEndpoint)
                .credential(credential)
                .buildAsyncClient();
    }

    public KeyClient keyClient() {
        return new KeyClientBuilder()
                .vaultUrl(vaultEndpoint)
                .credential(credential)
                .buildClient();
    }

    public KeyAsyncClient keyAsyncClient() {
        return new KeyClientBuilder()
                .vaultUrl(vaultEndpoint)
                .credential(credential)
                .buildAsyncClient();
    }

    public TokenCredential credential() {
        return credential;
    }

    public String keyName() {
        return keyName;
    }

    public String containerName() {
        return containerName;
    }

    private static String requireEnvironmentVariable(Map<String, String> environment, String name) {
        String value = environment.get(name);
        if (value == null || value.isBlank()) {
            throw new IllegalStateException("Required environment variable is missing: " + name);
        }
        return value;
    }
}

package com.example.encryptedblob;

import java.util.Base64;
import java.util.Map;

final class BlobEncryptionMetadata {
    private static final String CONTENT_ALGORITHM = "encryption-algorithm";
    private static final String WRAP_ALGORITHM = "key-wrap-algorithm";
    private static final String KEY_ID = "key-id";
    private static final String WRAPPED_KEY = "wrapped-key";
    private static final String IV = "iv";

    private final String keyId;
    private final byte[] wrappedKey;
    private final byte[] iv;

    private BlobEncryptionMetadata(String keyId, byte[] wrappedKey, byte[] iv) {
        this.keyId = keyId;
        this.wrappedKey = wrappedKey;
        this.iv = iv;
    }

    static BlobEncryptionMetadata create(String keyId, byte[] wrappedKey, byte[] iv) {
        return new BlobEncryptionMetadata(keyId, wrappedKey, iv);
    }

    static BlobEncryptionMetadata parse(Map<String, String> metadata) {
        String contentAlgorithm = required(metadata, CONTENT_ALGORITHM);
        String wrapAlgorithm = required(metadata, WRAP_ALGORITHM);
        if (!EnvelopeCrypto.CONTENT_ALGORITHM.equals(contentAlgorithm)) {
            throw new EncryptionStorageException("Unsupported content encryption algorithm: " + contentAlgorithm);
        }
        if (!KeyManagementService.WRAP_ALGORITHM_NAME.equals(wrapAlgorithm)) {
            throw new EncryptionStorageException("Unsupported key wrap algorithm: " + wrapAlgorithm);
        }

        try {
            return new BlobEncryptionMetadata(
                    required(metadata, KEY_ID),
                    Base64.getDecoder().decode(required(metadata, WRAPPED_KEY)),
                    Base64.getDecoder().decode(required(metadata, IV)));
        } catch (IllegalArgumentException exception) {
            throw new EncryptionStorageException("Blob encryption metadata contains invalid base64", exception);
        }
    }

    Map<String, String> toMap() {
        Base64.Encoder encoder = Base64.getEncoder();
        return Map.of(
                CONTENT_ALGORITHM, EnvelopeCrypto.CONTENT_ALGORITHM,
                WRAP_ALGORITHM, KeyManagementService.WRAP_ALGORITHM_NAME,
                KEY_ID, keyId,
                WRAPPED_KEY, encoder.encodeToString(wrappedKey),
                IV, encoder.encodeToString(iv));
    }

    String keyId() {
        return keyId;
    }

    byte[] wrappedKey() {
        return wrappedKey;
    }

    byte[] iv() {
        return iv;
    }

    byte[] authenticatedMetadata() {
        return EnvelopeCrypto.authenticatedMetadata(keyId, wrappedKey);
    }

    private static String required(Map<String, String> metadata, String name) {
        String value = metadata.get(name);
        if (value == null || value.isBlank()) {
            throw new EncryptionStorageException("Blob is missing encryption metadata field: " + name);
        }
        return value;
    }
}

package com.example.encryptedblob;

import java.util.Arrays;

final class DataKey implements AutoCloseable {
    private static final int AES_256_KEY_BYTES = 32;

    private final byte[] bytes;
    private boolean destroyed;

    DataKey(byte[] bytes) {
        if (bytes.length != AES_256_KEY_BYTES) {
            Arrays.fill(bytes, (byte) 0);
            throw new EncryptionStorageException(
                    "Unwrapped data key is not a 256-bit AES key");
        }
        this.bytes = bytes;
    }

    byte[] bytes() {
        if (destroyed) {
            throw new IllegalStateException("Data encryption key has already been destroyed");
        }
        return bytes;
    }

    @Override
    public void close() {
        Arrays.fill(bytes, (byte) 0);
        destroyed = true;
    }
}

package com.example.encryptedblob;

import com.azure.core.util.BinaryData;
import com.azure.storage.blob.BlobAsyncClient;
import com.azure.storage.blob.BlobContainerAsyncClient;
import com.azure.storage.blob.models.BlobStorageException;
import com.azure.storage.blob.options.BlobParallelUploadOptions;
import reactor.core.publisher.Mono;
import reactor.core.scheduler.Schedulers;

import java.nio.file.Files;
import java.nio.file.Path;
import java.security.SecureRandom;
import java.util.Base64;

public final class EncryptedBlobAsyncClient {
    private final BlobContainerAsyncClient containerClient;
    private final AsyncKeyManagementService keyManagement;
    private final SecureRandom secureRandom;

    public EncryptedBlobAsyncClient(
            BlobContainerAsyncClient containerClient,
            AsyncKeyManagementService keyManagement) {
        this(containerClient, keyManagement, new SecureRandom());
    }

    EncryptedBlobAsyncClient(
            BlobContainerAsyncClient containerClient,
            AsyncKeyManagementService keyManagement,
            SecureRandom secureRandom) {
        this.containerClient = containerClient;
        this.keyManagement = keyManagement;
        this.secureRandom = secureRandom;
    }

    public Mono<EncryptedBlobInfo> upload(String blobName, byte[] plaintext) {
        return keyManagement.generateAndWrapDataKey()
                .flatMap(protectedKey -> Mono.using(
                        () -> protectedKey,
                        key -> {
                            byte[] iv = EnvelopeCrypto.generateIv(secureRandom);
                            BlobEncryptionMetadata metadata = BlobEncryptionMetadata.create(
                                    key.keyId(), key.wrappedKey(), iv);
                            byte[] ciphertext = EnvelopeCrypto.encrypt(
                                    plaintext,
                                    key.dataKey().bytes(),
                                    iv,
                                    metadata.authenticatedMetadata());
                            BlobAsyncClient blobClient = containerClient.getBlobAsyncClient(blobName);
                            BlobParallelUploadOptions options =
                                    new BlobParallelUploadOptions(BinaryData.fromBytes(ciphertext))
                                            .setMetadata(metadata.toMap());
                            return blobClient.uploadWithResponse(options)
                                    .thenReturn(new EncryptedBlobInfo(
                                            key.keyId(),
                                            Base64.getEncoder().encodeToString(key.wrappedKey())));
                        },
                        ProtectedDataKey::close))
                .onErrorMap(
                        BlobStorageException.class,
                        exception -> blobException("upload", blobName, exception));
    }

    public Mono<EncryptedBlobInfo> uploadFile(String blobName, Path source) {
        return Mono.fromCallable(() -> Files.readAllBytes(source))
                .subscribeOn(Schedulers.boundedElastic())
                .onErrorMap(
                        exception -> new EncryptionStorageException(
                                "Could not read source file: " + source, exception))
                .flatMap(bytes -> upload(blobName, bytes));
    }

    public Mono<byte[]> download(String blobName) {
        BlobAsyncClient blobClient = containerClient.getBlobAsyncClient(blobName);
        return blobClient.getProperties()
                .map(properties -> BlobEncryptionMetadata.parse(properties.getMetadata()))
                .zipWith(blobClient.downloadContent())
                .flatMap(tuple -> {
                    BlobEncryptionMetadata metadata = tuple.getT1();
                    byte[] ciphertext = tuple.getT2().toBytes();
                    return keyManagement.unwrapDataKey(metadata.keyId(), metadata.wrappedKey())
                            .map(dataKey -> {
                                try (dataKey) {
                                    return EnvelopeCrypto.decrypt(
                                            ciphertext,
                                            dataKey.bytes(),
                                            metadata.iv(),
                                            metadata.authenticatedMetadata());
                                }
                            });
                })
                .onErrorMap(
                        BlobStorageException.class,
                        exception -> blobException("download", blobName, exception));
    }

    public Mono<Void> downloadFile(String blobName, Path destination) {
        return download(blobName)
                .flatMap(bytes -> Mono.fromCallable(() -> Files.write(destination, bytes))
                        .subscribeOn(Schedulers.boundedElastic())
                        .onErrorMap(
                                exception -> new EncryptionStorageException(
                                        "Could not write destination file: " + destination, exception)))
                .then();
    }

    private static EncryptionStorageException blobException(
            String operation,
            String blobName,
            BlobStorageException exception) {
        String errorCode = exception.getErrorCode() == null
                ? "unknown"
                : exception.getErrorCode().toString();
        return new EncryptionStorageException(
                "Blob Storage could not " + operation + " blob '" + blobName
                        + "' (HTTP " + exception.getStatusCode() + ", " + errorCode + ")",
                exception);
    }
}

package com.example.encryptedblob;

import com.azure.core.util.BinaryData;
import com.azure.storage.blob.BlobClient;
import com.azure.storage.blob.BlobContainerClient;
import com.azure.storage.blob.models.BlobStorageException;
import com.azure.storage.blob.options.BlobParallelUploadOptions;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.SecureRandom;
import java.util.Base64;

public final class EncryptedBlobClient {
    private final BlobContainerClient containerClient;
    private final KeyManagementService keyManagement;
    private final SecureRandom secureRandom;

    public EncryptedBlobClient(
            BlobContainerClient containerClient,
            KeyManagementService keyManagement) {
        this(containerClient, keyManagement, new SecureRandom());
    }

    EncryptedBlobClient(
            BlobContainerClient containerClient,
            KeyManagementService keyManagement,
            SecureRandom secureRandom) {
        this.containerClient = containerClient;
        this.keyManagement = keyManagement;
        this.secureRandom = secureRandom;
    }

    public EncryptedBlobInfo upload(String blobName, byte[] plaintext) {
        try (ProtectedDataKey protectedKey = keyManagement.generateAndWrapDataKey()) {
            byte[] iv = EnvelopeCrypto.generateIv(secureRandom);
            BlobEncryptionMetadata metadata = BlobEncryptionMetadata.create(
                    protectedKey.keyId(), protectedKey.wrappedKey(), iv);
            byte[] ciphertext = EnvelopeCrypto.encrypt(
                    plaintext,
                    protectedKey.dataKey().bytes(),
                    iv,
                    metadata.authenticatedMetadata());

            try {
                BlobClient blobClient = containerClient.getBlobClient(blobName);
                blobClient.uploadWithResponse(
                        new BlobParallelUploadOptions(BinaryData.fromBytes(ciphertext))
                                .setMetadata(metadata.toMap()),
                        null,
                        null);
            } catch (BlobStorageException exception) {
                throw blobException("upload", blobName, exception);
            }

            return new EncryptedBlobInfo(
                    protectedKey.keyId(),
                    Base64.getEncoder().encodeToString(protectedKey.wrappedKey()));
        }
    }

    public EncryptedBlobInfo uploadFile(String blobName, Path source) {
        try {
            return upload(blobName, Files.readAllBytes(source));
        } catch (IOException exception) {
            throw new EncryptionStorageException("Could not read source file: " + source, exception);
        }
    }

    public byte[] download(String blobName) {
        BlobClient blobClient = containerClient.getBlobClient(blobName);
        BlobEncryptionMetadata metadata;
        byte[] ciphertext;
        try {
            metadata = BlobEncryptionMetadata.parse(blobClient.getProperties().getMetadata());
            ciphertext = blobClient.downloadContent().toBytes();
        } catch (BlobStorageException exception) {
            throw blobException("download", blobName, exception);
        }

        try (DataKey dataKey = keyManagement.unwrapDataKey(metadata.keyId(), metadata.wrappedKey())) {
            return EnvelopeCrypto.decrypt(
                    ciphertext,
                    dataKey.bytes(),
                    metadata.iv(),
                    metadata.authenticatedMetadata());
        }
    }

    public void downloadFile(String blobName, Path destination) {
        try {
            Files.write(destination, download(blobName));
        } catch (IOException exception) {
            throw new EncryptionStorageException("Could not write destination file: " + destination, exception);
        }
    }

    private static EncryptionStorageException blobException(
            String operation,
            String blobName,
            BlobStorageException exception) {
        String errorCode = exception.getErrorCode() == null
                ? "unknown"
                : exception.getErrorCode().toString();
        return new EncryptionStorageException(
                "Blob Storage could not " + operation + " blob '" + blobName
                        + "' (HTTP " + exception.getStatusCode() + ", " + errorCode + ")",
                exception);
    }
}

