+        return Map.of(
+                CONTENT_ALGORITHM, EnvelopeCrypto.CONTENT_ALGORITHM,
+                WRAP_ALGORITHM, KeyManagementService.WRAP_ALGORITHM_NAME,
+                KEY_ID, keyId,
+                WRAPPED_KEY, encoder.encodeToString(wrappedKey),
+                IV, encoder.encodeToString(iv));
+    }
